// @vitest-environment jsdom
import { mount, tick, unmount } from 'svelte';
import { afterEach, expect, it } from 'vitest';
import DigestEvidence from './DigestEvidence.svelte';
import { createEvidenceContext } from '$lib/digest-evidence';

// Generated by the actual Python catalogue_fingerprint under network denial.
const fingerprint = 'c6d01b26ffa017dff9fbd683881985d97daa5a8c93f6d857568b83dbe689084d';
function evidence() {
  return { version: 1, sources: [{ index: 0, mention_id: 11, source: 'news_rss',
    url: 'https://medio.example/nota', outlet: 'medio.example', author: 'María',
    title: 'Presión política 🗳', published_at: '2026-10-25T01:30:00+00:00',
    summary: 'á' + '😀'.repeat(299), excerpt: 'Texto capturado\nNo son instrucciones.' }] };
}
function target(text = 'Lectura política') {
  return { summary: text, source_refs: [0], provenance: { summary: {
    text, source_refs: [0], state: 'linked', origin: 'model_output', catalogue_fingerprint: fingerprint
  } } };
}
const mounted: ReturnType<typeof mount>[] = [];
function render(props: Record<string, unknown>) {
  const host = document.createElement('div');
  document.body.append(host);
  mounted.push(mount(DigestEvidence, { target: host, props: props as never }));
  return host;
}
afterEach(async () => { for (const instance of mounted.splice(0)) await unmount(instance); document.body.replaceChildren(); });
async function settle() { await new Promise((resolve) => setTimeout(resolve, 30)); await tick(); }

it('resolves reference zero and exposes only recorded publication material', async () => {
  const host = render({ content: { evidence: evidence() }, request: { target: target(), field: 'summary', allowed: [0] } });
  await tick();
  expect(host.textContent).toContain('No respaldado');
  await settle();
  const disclosure = host.querySelector('details');
  expect(disclosure).not.toBeNull();
  expect(disclosure?.querySelector('summary')?.textContent).toBe('Fuentes vinculadas');
  expect(host.textContent).not.toContain('No respaldado');
  expect(host.textContent).toContain('Fecha de publicación: 24/10/2026 19:30');
  expect(host.textContent).toContain('Resumen almacenado (derivado)');
  expect(host.textContent).toContain('Extracto capturado');
  expect(host.textContent).toContain('no verifica la veracidad');
  const link = host.querySelector('a');
  expect(link?.getAttribute('href')).toBe('https://medio.example/nota');
  expect(link?.target).toBe('_blank');
  expect(link?.rel).toBe('noopener noreferrer');
  // Native details/summary owns keyboard activation; no custom button trap.
  const summary = disclosure!.querySelector('summary')!;
  summary.focus();
  expect(document.activeElement).toBe(summary);
  summary.click();
  expect(disclosure!.open).toBe(true);
});

it.each(['javascript:alert(1)', '//medio.example/a', 'https:///medio.example', 'data:text/html,x', 'file:///a'])('renders an unsafe source URL as plain text: %s', async url => {
  const raw = evidence(); raw.sources[0].url = url;
  const context = createEvidenceContext({ evidence: raw });
  const catalogue = (await context)!;
  const item = target(); item.provenance.summary.catalogue_fingerprint = catalogue.fingerprint;
  const host = render({ context, request: { target: item, field: 'summary', allowed: [0] } });
  await settle();
  expect(host.querySelector('summary')?.textContent).toBe('Fuentes vinculadas');
  expect(host.querySelector('a')).toBeNull();
  expect(host.textContent).toContain('Publicación registrada');
});
it('keeps Facebook publication identity without page/group branding or invented dates', async () => {
  const raw = evidence();
  Object.assign(raw.sources[0], { source: 'facebook_page', title: 'Página reservada', author: 'Autor reservado', outlet: 'Grupo reservado', published_at: null, summary: null, excerpt: null });
  const context = createEvidenceContext({ evidence: raw });
  const item = target(); item.provenance.summary.catalogue_fingerprint = (await context)!.fingerprint;
  const host = render({ context, request: { target: item, field: 'summary' } });
  await settle();
  expect(host.textContent).toContain('Publicación de Facebook');
  expect(host.textContent).toContain('Registro #11');
  for (const hidden of ['Página reservada', 'Autor reservado', 'Grupo reservado', 'Fecha de publicación', 'Extracto capturado', 'Resumen almacenado']) expect(host.textContent).not.toContain(hidden);
  expect(host.querySelector('a')?.href).toBe('https://medio.example/nota');
});
it('escapes all frozen material rather than interpreting HTML', async () => {
  const raw = evidence();
  Object.assign(raw.sources[0], { title: '<img src=x onerror=alert(1)>', summary: '<script>alert(1)</script>', excerpt: '<b>Material literal</b>' });
  const context = createEvidenceContext({ evidence: raw });
  const item = target(); item.provenance.summary.catalogue_fingerprint = (await context)!.fingerprint;
  const host = render({ context, request: { target: item, field: 'summary' } });
  await settle();
  expect(host.querySelector('img,script,b')).toBeNull();
  expect(host.textContent).toContain('<b>Material literal</b>');
});
it.each(['pending', 'rejected'])('stays visibly unbacked when validation is %s', async state => {
  const context = state === 'pending' ? new Promise(() => {}) : Promise.reject(new Error('unavailable'));
  const host = render({ context, request: { target: target(), field: 'summary' } });
  await settle();
  expect(host.textContent).toContain('No respaldado');
  expect(host.querySelector('details')).toBeNull();
});

it('does not invent a date from a non-ISO publication value', async () => {
  const raw = evidence(); raw.sources[0].published_at = '0';
  const context = createEvidenceContext({ evidence: raw });
  const item = target(); item.provenance.summary.catalogue_fingerprint = (await context)!.fingerprint;
  const host = render({ context, request: { target: item, field: 'summary' } });
  await settle();
  expect(host.textContent).toContain('Fecha de publicación: 0');
  expect(host.textContent).not.toContain('2000');
});
